#include <iostream>

int clamp_value(int value, int low, int high) {
    if (value < low) {
        return low;
    }
    if (value > high) {
        return high;
    }
    return value; // TODO: make the helper generic
}

int main() {
    std::cout << clamp_value(12, 0, 10) << "\n";
    return 0;
}
